with matched_keys as (select id from customers except select id from customers where name is not null), kept_rows as (select s.* from customers s join matched_keys k on s.id = k.id) select case when credit_limit >= 18000 then 'PREMIUM' else 'STANDARD' end as credit_limit_tier, size(collect_set(country)) as num_countries, max(age) as max_age, sort_array(collect_set(city)) as city_list, percentile_approx(age, array(0.25, 0.5, 0.75)) as age_quartiles, stddev_samp(age) as age_stddev from kept_rows group by case when credit_limit >= 18000 then 'PREMIUM' else 'STANDARD' end order by credit_limit_tier desc
